```python
import sys

def sieve(limit):
    is_prime = [True] * (limit + 1)
    primes = []
    for i in range(2, limit + 1):
        if not is_prime[i]:
            continue
        primes.append(i)
        if i * i > limit:
            continue
        for j in range(i * i, limit + 1, i):
            is_prime[j] = False
    return primes

primes = sieve(32000)

def factorize(x):
    factors = []
    for p in primes:
        if p * p > x:
            break
        if x % p == 0:
            factors.append(p)
            while x % p == 0:
                x //= p
    if x > 1:
        factors.append(x)
    return factors

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])
    a = list(map(int, data[2:2 + n]))

    # 质因子映射
    pid = {}
    pc = 0
    fac_ids = [[] for _ in range(n)]
    for i, x in enumerate(a):
        if x == 1:
            continue
        for p in factorize(x):
            if p not in pid:
                pid[p] = pc
                pc += 1
            fac_ids[i].append(pid[p])

    # 去重并排序，用于二分
    vals = sorted(set(a))

    def check(M):
        if k == 1:
            return any(x <= M for x in a)
        best = [0] * pc
        mx = 0
        for i, x in enumerate(a):
            if x > M or x == 1:
                continue
            dp = 1
            for pid in fac_ids[i]:
                if best[pid] + 1 > dp:
                    dp = best[pid] + 1
            if dp > mx:
                mx = dp
            if mx >= k:
                return True
            for pid in fac_ids[i]:
                if best[pid] < dp:
                    best[pid] = dp
        return False

    lo, hi = 0, len(vals) - 1
    ans = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if check(vals[mid]):
            ans = vals[mid]
            hi = mid - 1
        else:
            lo = mid + 1
    print(ans)

if __name__ == "__main__":
    main()
