### Java

```java
import java.io.*;
import java.util.*;

public class Main {
    static List<Integer> primes = new ArrayList<>();

    static void initPrimes() {
        int N = 32000;
        boolean[] isPrime = new boolean[N + 1];
        Arrays.fill(isPrime, true);
        for (int i = 2; i <= N; i++) {
            if (!isPrime[i]) continue;
            primes.add(i);
            if ((long) i * i > N) continue;
            for (int j = i * i; j <= N; j += i) {
                isPrime[j] = false;
            }
        }
    }

    static List<Integer> factorize(long x) {
        List<Integer> fac = new ArrayList<>();
        for (int p : primes) {
            if ((long) p * p > x) break;
            if (x % p == 0) {
                fac.add(p);
                while (x % p == 0) x /= p;
            }
        }
        if (x > 1) fac.add((int) x);
        return fac;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        long[] a = new long[n];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) {
            a[i] = Long.parseLong(st.nextToken());
        }

        initPrimes();
        Map<Integer, Integer> pidMap = new HashMap<>();
        int pc = 0;
        List<Integer>[] facIds = new List[n];
        for (int i = 0; i < n; i++) facIds[i] = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (a[i] == 1) continue;
            for (int p : factorize(a[i])) {
                Integer id = pidMap.get(p);
                if (id == null) {
                    id = pc++;
                    pidMap.put(p, id);
                }
                facIds[i].add(id);
            }
        }

        long[] vals = a.clone();
        Arrays.sort(vals);
        int idx = 0;
        for (int i = 0; i < n; i++) {
            if (i == 0 || vals[i] != vals[idx - 1]) {
                vals[idx++] = vals[i];
            }
        }
        int m = idx;

        int lo = 0, hi = m - 1;
        long ans = -1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            long M = vals[mid];
            boolean ok;
            if (k == 1) {
                ok = false;
                for (long x : a) {
                    if (x <= M) { ok = true; break; }
                }
            } else {
                int[] best = new int[pc];
                int mx = 0;
                ok = false;
                for (int i = 0; i < n; i++) {
                    if (a[i] > M || a[i] == 1) continue;
                    int dp = 1;
                    for (int pid : facIds[i]) {
                        if (best[pid] + 1 > dp) dp = best[pid] + 1;
                    }
                    if (dp > mx) mx = dp;
                    if (mx >= k) { ok = true; break; }
                    for (int pid : facIds[i]) {
                        if (best[pid] < dp) best[pid] = dp;
                    }
                }
            }
            if (ok) { ans = M; hi = mid - 1; }
            else lo = mid + 1;
        }
        System.out.println(ans);
    }
}
