#include <bits/stdc++.h>
using namespace std;

vector<int> primes;
void init_primes() {
    const int N = 32000;
    vector<bool> is_prime(N + 1, true);
    for (int i = 2; i <= N; ++i) {
        if (!is_prime[i]) continue;
        primes.push_back(i);
        if (1LL * i * i > N) continue;
        for (int j = i * i; j <= N; j += i) {
            is_prime[j] = false;
        }
    }
}

vector<int> factorize(long long x) {
    vector<int> fac;
    for (int p : primes) {
        if (1LL * p * p > x) break;
        if (x % p == 0) {
            fac.push_back(p);
            while (x % p == 0) x /= p;
        }
    }
    if (x > 1) fac.push_back((int)x);
    return fac;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    init_primes();
    int n, k;
    cin >> n >> k;
    vector<long long> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    unordered_map<int, int> pid;
    int pc = 0;
    vector<vector<int>> fac_ids(n);
    for (int i = 0; i < n; ++i) {
        if (a[i] == 1) continue;
        for (int p : factorize(a[i])) {
            if (!pid.count(p)) pid[p] = pc++;
            fac_ids[i].push_back(pid[p]);
        }
    }

    auto check = [&](long long M) -> bool {
        if (k == 1) {
            for (long long x : a) if (x <= M) return true;
            return false;
        }
        vector<int> best(pc, 0);
        int mx = 0;
        for (int i = 0; i < n; ++i) {
            if (a[i] > M || a[i] == 1) continue;
            int dp = 1;
            for (int id : fac_ids[i]) dp = max(dp, best[id] + 1);
            mx = max(mx, dp);
            if (mx >= k) return true;
            for (int id : fac_ids[i]) {
                if (best[id] < dp) best[id] = dp;
            }
        }
        return false;
    };

    vector<long long> vals = a;
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());

    long long ans = -1;
    int lo = 0, hi = (int)vals.size() - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (check(vals[mid])) {
            ans = vals[mid];
            hi = mid - 1;
        } else {
            lo = mid + 1;
        }
    }
    cout << ans << '\n';
    return 0;
}
